{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Restorative Sound Events</title>
  <meta name="description" content="A sanctuary of tuned sound gatherings, private sessions, and intention practices in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <svg class="site-pattern" aria-hidden="true" width="0" height="0" style="position:absolute;left:-9999px;">
    <defs>
      <pattern id="p" patternUnits="userSpaceOnUse" width="60" height="60">
        <rect width="60" height="60" fill="#efe5da"></rect>
        <path d="M0 30c10-8 20-8 30 0s20 8 30 0" stroke="#d6bba6" stroke-width="1" fill="none"/>
      </pattern>
    </defs>
  </svg>

  <header class="topbar">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private Sessions</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">Story</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="/book.html">Reserve</a>
      </nav>
      <button class="try-btn" id="open-try">Try it now</button>
    </div>
  </header>

  <main>
    <section class="hero reveal" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1 class="title">Sound that steadies attention and invites soft perspective</h1>
          <p class="subtitle">{{TAGLINE}}</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button class="btn ghost" id="hero-try">Try a 4-minute exercise</button>
          </div>
        </div>
        <div class="hero-panel">
          <div class="next-event" aria-live="polite">
            <h3>Next gathering</h3>
            <p class="event-date">Sat • Mar 6 • 7:00pm</p>
            <p class="event-location">Intimate circle in {{CITY}}, {{STATE}}</p>
            <a class="btn small" href="/events.html">See the calendar</a>
          </div>
          <ul class="mini-calendar">
            <li><strong>Mar 6</strong> • Evening Circle</li>
            <li><strong>Mar 20</strong> • Deep Drift Session</li>
            <li><strong>Apr 3</strong> • Rest & Reset</li>
            <li><strong>Apr 17</strong> • New Moon Intention</li>
          </ul>
        </div>
      </div>
    </section>

    <section class="social-proof reveal" id="social-proof">
      <div class="wrap">
        <h2>What people take away</h2>
        <div class="quotes">
          <blockquote>"A steady container — I left more spacious than when I arrived." — A.</blockquote>
          <blockquote>"Unexpected clarity after the softest sounds." — R.</blockquote>
          <blockquote>"The best sleep I’ve had in months." — N.</blockquote>
        </div>
      </div>
    </section>

    <section class="benefits reveal" id="benefits">
      <div class="wrap">
        <h2>Offerings & benefits</h2>
        <div class="cards">
          <div class="card">
            <h3>Circles</h3>
            <p>Group gatherings designed to allow attention to settle. Comfortable seating and optional cushions provided.</p>
          </div>
          <div class="card">
            <h3>One-on-one sessions</h3>
            <p>Focused time for intention work, restoration, or ritual. Sessions are paced to your nervous system.</p>
          </div>
          <div class="card">
            <h3>Mini retreat days (VIP Day)</h3>
            <p>Immersive single-day programs for reset and recalibration, crafted for small cohorts or private bookings.</p>
          </div>
        </div>
        <p class="contra">Contraindications: Sound practices are gentle but not medical treatments. If you are pregnant, have epilepsy, uncontrolled hypertension, recent surgery, or implanted medical devices, consult your healthcare provider before participating. If in doubt, contact us at {{PHONE}} or {{EMAIL}}.</p>
      </div>
    </section>

    <section class="process reveal" id="process">
      <div class="wrap">
        <h2>How an evening unfolds</h2>
        <ol class="process-list">
          <li><strong>Arrival & settling:</strong> Slow transitions, brief orientation.</li>
          <li><strong>Intention:</strong> A short, guided prompt to orient attention.</li>
          <li><strong>Sound period:</strong> Layered tones, pauses, and space for reflection.</li>
          <li><strong>Closure:</strong> Soft re-entry and optional journaling.</li>
        </ol>
      </div>
    </section>

    <section class="faq reveal" id="faq">
      <div class="wrap">
        <h2>Common questions</h2>
        <details>
          <summary>What should I bring?</summary>
          <p>Bring anything that helps you be comfortable: a blanket, cushion, or eye mask. We provide extra mats and seating.</p>
        </details>
        <details>
          <summary>Are sessions suitable for beginners?</summary>
          <p>Yes. Sessions are accessible; facilitators give gentle cues and alternatives. If you have specific needs, please contact us.</p>
        </details>
        <details>
          <summary>Refund & cancellation</summary>
          <p>Tickets refundable up to 48 hours prior to the event. Private sessions have a separate policy; enquire when booking.</p>
        </details>
      </div>
    </section>

    <section class="cta reveal" id="final-cta">
      <div class="wrap final-cta-grid">
        <div>
          <h2>Ready to reserve a place for quiet focus?</h2>
          <p>Choose a circle seat or book a private reset. Prefer to speak directly? Call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
        </div>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Reserve a spot</a>
          <a class="btn ghost" href="/contact.html">Contact team</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="wrap">
      <div class="foot-left">
        <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</p>
      </div>
      <div class="foot-right">
        <a href="/privacy.html">Privacy</a>
        <a href="/terms.html">Terms</a>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="guide-modal" class="modal" aria-hidden="true">
    <div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="guide-title">
      <button class="modal-close" id="close-guide">Close</button>
      <h3 id="guide-title">A short guided practice</h3>
      <div class="guide-content">
        <div id="guide-step" class="guide-step">Ready to begin a 4-minute calibration?</div>
        <div id="guide-timer" class="guide-timer">04:00</div>
        <div class="guide-controls">
          <button id="start-guide" class="btn primary">Start</button>
          <button id="pause-guide" class="btn ghost" disabled>Pause</button>
          <button id="skip-step" class="btn ghost">Skip</button>
        </div>
        <div id="journal-prompt" class="journal" hidden>
          <label for="journal-entry">Quick reflection (optional)</label>
          <textarea id="journal-entry" rows="4" placeholder="A word, a line, or nothing at all..."></textarea>
          <button id="save-journal" class="btn small">Save</button>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
