{"path":"assets/css/styles.css","content":":root{--bg:#f7efe8;--accent:#6b4f3a;--muted:#9b8a7b;--card:#fff;--accent-2:#caa07b}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--accent);background:var(--bg);line-height:1.5}
.wrap{max-width:1100px;margin:0 auto;padding:2rem}
.topbar{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);border-bottom:1px solid rgba(107,79,58,0.06)}
.topbar .wrap{display:flex;align-items:center;gap:1rem}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.nav{margin-left:auto;display:flex;gap:1rem}
.nav a{color:var(--accent);text-decoration:none;padding:0.5rem 0.6rem;border-radius:6px}
.nav a.cta{background:var(--accent);color:#fff;padding:0.5rem 0.9rem}
.try-btn{margin-left:1rem;background:transparent;border:1px solid var(--accent);padding:0.4rem 0.7rem;border-radius:6px}
.hero{background-image:url('/assets/img/pattern.svg');background-repeat:repeat;padding:3rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:center}
.title{font-size:1.9rem;margin:0 0 0.5rem}
.subtitle{color:var(--muted);margin:0 0 1rem}
.btn{display:inline-block;text-decoration:none;border:0;padding:0.6rem 1rem;border-radius:8px;background:transparent;color:var(--accent);cursor:pointer}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{border:1px solid rgba(107,79,58,0.12)}
.btn.small{padding:0.3rem 0.6rem;font-size:0.9rem}
.hero-panel{background:linear-gradient(180deg,#fff, #fbf6f2);padding:1rem;border-radius:12px;border:1px solid rgba(107,79,58,0.05)}
.next-event h3{margin:0 0 0.3rem}
.mini-calendar{list-style:none;padding:0;margin:1rem 0 0}
.mini-calendar li{padding:0.3rem 0;border-top:1px dashed rgba(107,79,58,0.05);font-size:0.95rem}
.section{padding:3rem 0}
.cards{display:flex;gap:1rem;margin-top:1rem}
.card{background:var(--card);padding:1rem;border-radius:10px;box-shadow:0 1px 6px rgba(16,16,16,0.04);flex:1}
.contra{margin-top:1rem;color:#7a5f50;font-size:0.95rem}
.process-list{padding-left:1rem}
.quotes{display:flex;gap:1rem}
.quotes blockquote{background:var(--card);padding:1rem;border-radius:8px;margin:0;flex:1;font-style:italic;color:var(--muted)}
.final-cta-grid{display:flex;justify-content:space-between;align-items:center}
.footer{border-top:1px solid rgba(107,79,58,0.05);padding:1rem 0;margin-top:2rem}
.footer a{color:var(--muted);text-decoration:none;margin-left:1rem}

/* modal */
.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(14,12,10,0.35);padding:2rem}
.modal[aria-hidden="false"]{display:flex}
.modal-dialog{background:var(--card);padding:1.5rem;border-radius:12px;max-width:520px;width:100%;position:relative}
.modal-close{position:absolute;right:12px;top:12px;border:0;background:transparent}
.guide-timer{font-family:monospace;font-size:1.3rem;margin:0.8rem 0}
.guide-step{font-weight:600}
.guide-controls{display:flex;gap:0.5rem}
.journal{margin-top:1rem}
.journal textarea{width:100%;padding:0.6rem;border-radius:8px;border:1px solid rgba(107,79,58,0.08)}

/* reveal animations */
.reveal{opacity:0;transform:translateY(18px);transition:opacity 420ms ease,transform 420ms cubic-bezier(.2,.8,.2,1)}
.reveal.visible{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}

/* responsiveness */
@media (max-width:800px){
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  .final-cta-grid{flex-direction:column;gap:1rem}
  .quotes{flex-direction:column}
  .cards{flex-direction:column}
}"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qs(sel, ctx){return (ctx||document).querySelector(sel)}
  function qsa(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year
  var year = qs('#year'); if(year) year.textContent = new Date().getFullYear();

  // Modal logic for guided exercise
  var modal = qs('#guide-modal');
  var openBtns = [qs('#open-try'), qs('#hero-try')].filter(Boolean);
  var closeBtn = qs('#close-guide');
  var startBtn = qs('#start-guide');
  var pauseBtn = qs('#pause-guide');
  var skipBtn = qs('#skip-step');
  var guideStep = qs('#guide-step');
  var guideTimer = qs('#guide-timer');
  var journal = qs('#journal-prompt');
  var journalEntry = qs('#journal-entry');
  var saveJournal = qs('#save-journal');

  var totalSeconds = 240; // 4 minutes
  var remaining = totalSeconds;
  var timerId = null;
  var steps = [
    {label:'Settle your posture. Take three slow inhales and exhales.', duration:30},
    {label:'Soften focus. Notice any tension and let it soften.', duration:60},
    {label:'Listen to the space between tones. Breathe without forcing.', duration:90},
    {label:'Bring an intention to mind. Hold it softly.', duration:60}
  ];
  var currentStep = 0;

  function formatTime(sec){
    var m = Math.floor(sec/60).toString().padStart(2,'0');
    var s = (sec%60).toString().padStart(2,'0');
    return m+':'+s;
  }

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    modal.style.display='flex';
    remaining = totalSeconds;
    currentStep = 0;
    updateUI();
    // focus start button
    startBtn && startBtn.focus();
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    modal.style.display='none';
    stopTimer();
  }

  function updateUI(){
    guideTimer.textContent = formatTime(remaining);
    guideStep.textContent = steps[currentStep] ? steps[currentStep].label : 'Closing the exercise.';
    pauseBtn.disabled = !timerId;
    if(!steps[currentStep]){
      journal.hidden = false;
    }
  }

  function tick(){
    if(remaining<=0){
      advanceStep();
      return;
    }
    remaining--;
    updateUI();
  }

  function startTimer(){
    if(timerId) return;
    // respect reduced motion: if user prefers reduced motion, run minimal timing but avoid transitions
    timerId = setInterval(tick, 1000);
    updateUI();
  }
  function stopTimer(){
    clearInterval(timerId); timerId = null; updateUI();
  }

  function advanceStep(){
    // subtract current step duration from remaining and advance
    var step = steps[currentStep];
    if(step){ remaining = Math.max(0, remaining - step.duration); }
    currentStep++;
    if(currentStep < steps.length){
      // set remaining to remaining of next segments
      // compute remaining equal to sum of remain durations
      var sum = 0; for(var i=currentStep;i<steps.length;i++) sum += steps[i].duration;
      remaining = Math.max(0, Math.min(remaining, sum));
    } else {
      // finished
      remaining = 0;
      stopTimer();
      guideStep.textContent = 'Practice complete — take a moment. Would you like to note anything?';
      journal.hidden = false;
    }
    updateUI();
  }

  openBtns.forEach(function(b){ b.addEventListener('click', openModal) });
  closeBtn && closeBtn.addEventListener('click', closeModal);

  startBtn && startBtn.addEventListener('click', function(){
    // initialize remaining to full run if at start
    if(remaining<=0) remaining = totalSeconds;
    startTimer();
  });
  pauseBtn && pauseBtn.addEventListener('click', function(){ if(timerId) stopTimer(); else startTimer(); });
  skipBtn && skipBtn.addEventListener('click', function(){ advanceStep(); });
  saveJournal && saveJournal.addEventListener('click', function(){
    var text = journalEntry.value || '';
    // for now, store in localStorage as ephemeral note
    try{ localStorage.setItem('sb_journal_' + Date.now(), text); }catch(e){}
    saveJournal.textContent = 'Saved';
    setTimeout(function(){ saveJournal.textContent = 'Save'; journalEntry.value=''; },1200);
  });

  // Close modal on escape
  document.addEventListener('keydown', function(e){ if(e.key==='Escape' && modal.getAttribute('aria-hidden')==='false') closeModal(); });

  // Scroll reveal with prefers-reduced-motion support
  var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var revealItems = qsa('.reveal');
  if(prefersReduced){
    revealItems.forEach(function(el){ el.classList.add('visible'); });
  } else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){ if(entry.isIntersecting){ entry.target.classList.add('visible'); io.unobserve(entry.target); } });
    },{threshold:0.12});
    revealItems.forEach(function(el){ io.observe(el); });
  } else {
    // fallback: simple scroll listener
    function onScroll(){
      var h = window.innerHeight;
      revealItems.forEach(function(el){
        var r = el.getBoundingClientRect();
        if(r.top < h - 60){ el.classList.add('visible'); }
      });
    }
    onScroll();
    window.addEventListener('scroll', onScroll);
  }

  // Lightweight accessibility: ensure links open properly
  // No external analytics or libraries
})();"} 
